CREATE TABLE [constant_contact].[events_registrations] (
    [order_summary] NVARCHAR(MAX) NULL,
    [contact] NVARCHAR(MAX) NULL,
    [tickets] NVARCHAR(MAX) NULL,
    [display_physical_tickets] NVARCHAR(MAX) NULL,
